package com.paytaxihub.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="Shift") public class Shift { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Integer shiftId; @ManyToOne @JoinColumn(name="driver_id") private Driver driver; @ManyToOne @JoinColumn(name="vehicle_id") private Vehicle vehicle; private LocalDateTime startTime,endTime; private BigDecimal totalEarnings; private BigDecimal ownerTarget; private String qrToken; @Enumerated(EnumType.STRING) private ShiftStatus shiftStatus; public enum ShiftStatus{Active,Completed} public Shift(){} public Integer getShiftId(){return shiftId;} public void setShiftId(Integer v){shiftId=v;} public Driver getDriver(){return driver;} public void setDriver(Driver v){driver=v;} public Vehicle getVehicle(){return vehicle;} public void setVehicle(Vehicle v){vehicle=v;} public LocalDateTime getStartTime(){return startTime;} public void setStartTime(LocalDateTime v){startTime=v;} public LocalDateTime getEndTime(){return endTime;} public void setEndTime(LocalDateTime v){endTime=v;} public BigDecimal getTotalEarnings(){return totalEarnings;} public void setTotalEarnings(BigDecimal v){totalEarnings=v;} public BigDecimal getOwnerTarget(){return ownerTarget;} public void setOwnerTarget(BigDecimal v){ownerTarget=v;} public String getQrToken(){return qrToken;} public void setQrToken(String v){qrToken=v;} public ShiftStatus getShiftStatus(){return shiftStatus;} public void setShiftStatus(ShiftStatus v){shiftStatus=v;} }
